def keep_existing_entries(apps, schema_editor):
    """Tickets already scanned keep their entry, on the day they were scanned."""
    from core.models import event_day

    Ticket = apps.get_model("tickets", "Ticket")
    CheckIn = apps.get_model("scanner", "CheckIn")
    for ticket in Ticket.objects.filter(status="used", checked_in_at__isnull=False):
        CheckIn.objects.get_or_create(
            ticket=ticket, day=event_day(ticket.checked_in_at),
            defaults={"scanned_at": ticket.checked_in_at, "scanned_by_id": ticket.checked_in_by_id},
        )


